"use client";

import { useEffect, useState } from 'react';
import { useRouter } from 'next/navigation';
import { useAuth } from '@clerk/nextjs';

/**
 * Enhanced AuthRedirect component for handling authentication-based redirects
 * Uses multiple redirection strategies for reliability
 *
 * @param {Object} props
 * @param {string} props.redirectTo - URL to redirect to if conditions are met
 * @param {boolean} props.ifAuthenticated - Redirect if user is authenticated
 * @param {boolean} props.ifUnauthenticated - Redirect if user is not authenticated
 * @param {boolean} props.forceRedirect - Use window.location for more reliable redirect
 * @param {number} props.delay - Delay in ms before redirecting (default: 100)
 * @param {React.ReactNode} props.children - Content to render if no redirect happens
 */
export default function AuthRedirect({
  redirectTo = '/dashboard',
  ifAuthenticated = false,
  ifUnauthenticated = false,
  forceRedirect = false,
  delay = 100,
  children = null
}) {
  const router = useRouter();
  const { isLoaded, userId, isSignedIn } = useAuth();
  const [isRedirecting, setIsRedirecting] = useState(false);

  useEffect(() => {
    if (!isLoaded) return; // Wait until auth is loaded

    const isAuthenticated = !!userId && isSignedIn;

    // Redirect based on authentication state
    if ((ifAuthenticated && isAuthenticated) || (ifUnauthenticated && !isAuthenticated)) {
      if (isRedirecting) return; // Prevent multiple redirects

      setIsRedirecting(true);
      console.log(`AuthRedirect: Redirecting to ${redirectTo} (auth state: ${isAuthenticated ? 'authenticated' : 'unauthenticated'})`);

      // Add a small delay to ensure the redirect happens after any auth state changes
      const timer = setTimeout(() => {
        if (forceRedirect) {
          // Use direct location change for more reliable redirect
          window.location.href = redirectTo;
        } else {
          // Try Next.js router first
          try {
            router.push(redirectTo);

            // Fallback to direct location change if router doesn't redirect within 500ms
            const fallbackTimer = setTimeout(() => {
              if (document.location.pathname !== new URL(redirectTo, document.location.origin).pathname) {
                console.log("Router redirect didn't complete, using direct location change");
                window.location.href = redirectTo;
              }
            }, 500);

            return () => clearTimeout(fallbackTimer);
          } catch (error) {
            console.error("Error during router redirect:", error);
            window.location.href = redirectTo;
          }
        }
      }, delay);

      return () => clearTimeout(timer);
    }
  }, [isLoaded, userId, isSignedIn, ifAuthenticated, ifUnauthenticated, redirectTo, router, forceRedirect, delay, isRedirecting]);

  // Return children if no redirect or while waiting for auth to load
  return children;
}
